import json
from pathlib import Path
from generate_suite import actor, owner, check, deny, uid, header
cases=[]
def add(name,body): cases.append((name,body))
def mass(age,who=2,group='coroinha'):
    return owner()+f"INSERT INTO public.masses(title,starts_at,published) VALUES('QA time fixture',now()+interval '{age}',true) RETURNING id INTO mass_id; INSERT INTO public.assignments(mass_id,function_name,server_id,service_group) VALUES(mass_id,'QA function','{uid(who)}','{group}') RETURNING id INTO assignment_id;"
for group,who in [('coroinha',2),('cerimoniario',3)]:
    add(f'assignment/{group}/wrong-day-denied',mass('2 days',who,group)+actor(who)+"denied:=false; BEGIN PERFORM public.respond_assignment(assignment_id,'confirmar',''); EXCEPTION WHEN raise_exception THEN denied:=true; END;"+check('denied'))
    add(f'assignment/{group}/reason-required',mass('2 days',who,group)+actor(who)+"denied:=false; BEGIN PERFORM public.respond_assignment(assignment_id,'desmarcar',''); EXCEPTION WHEN raise_exception THEN denied:=true; END;"+check('denied'))
    add(f'assignment/{group}/withdraw',mass('2 days',who,group)+actor(who)+"PERFORM public.respond_assignment(assignment_id,'desmarcar','Justificativa QA');"+owner()+check("(SELECT status='desmarcado' FROM public.assignments WHERE id=assignment_id)"))
add('assignment/ceremonial-withdrawal-no-cross-group-notice',mass('2 days',3,'cerimoniario')+owner()+"DELETE FROM public.notifications;"+actor(3)+"PERFORM public.respond_assignment(assignment_id,'desmarcar','Justificativa QA');"+owner()+check(f"NOT EXISTS(SELECT 1 FROM public.notifications WHERE user_id IN ('{uid(2)}','{uid(4)}'))"))
for hours,expected in [(23,False),(25,True)]:
    add(f'archive/mass-{hours}h',mass(f'-{hours} hours')+owner()+"PERFORM public.archive_maintenance();"+check(f"(SELECT (archived_at IS NOT NULL)={str(expected).lower()} FROM public.masses WHERE id=mass_id)"))
add('archive/switch-off',mass('-25 hours')+actor(1)+"PERFORM public.developer_apply_automations('[{\"key\":\"archive_retention\",\"enabled\":false}]','DESENVOLVEDOR');"+owner()+"PERFORM public.archive_maintenance();"+check("(SELECT archived_at IS NULL FROM public.masses WHERE id=mass_id)"))
add('archive/permanent-delete-after-30-days',mass('-70 days')+owner()+"UPDATE public.masses SET archived_at=now()-interval '31 days' WHERE id=mass_id; PERFORM public.archive_maintenance();"+check('NOT EXISTS(SELECT 1 FROM public.masses WHERE id=mass_id)'))
add('archive/retain-before-30-days',mass('-70 days')+owner()+"UPDATE public.masses SET archived_at=now()-interval '29 days' WHERE id=mass_id; PERFORM public.archive_maintenance();"+check('EXISTS(SELECT 1 FROM public.masses WHERE id=mass_id)'))
for days,expected in [(29,False),(31,True)]:
    add(f'archive/notice-{days}d',owner()+f"INSERT INTO public.notifications(user_id,title,body,created_at) VALUES('{uid(2)}','QA archive','Body',now()-interval '{days} days') RETURNING id INTO record_id; PERFORM public.archive_maintenance();"+check(f"(SELECT (archived_at IS NOT NULL)={str(expected).lower()} FROM public.notifications WHERE id=record_id)"))
add('archive/closed-support',actor(2)+"result:=public.support_create('Dúvida','QA old ticket'); record_id:=(result->>'id')::uuid;"+actor(1)+"PERFORM public.support_close(record_id);"+owner()+"UPDATE public.support_tickets SET closed_at=now()-interval '31 days' WHERE id=record_id; PERFORM public.archive_maintenance();"+check('(SELECT archived_at IS NOT NULL FROM public.support_tickets WHERE id=record_id)'))
add('archive/open-support-preserved',actor(2)+"result:=public.support_create('Dúvida','QA open ticket'); record_id:=(result->>'id')::uuid;"+owner()+"UPDATE public.support_tickets SET created_at=now()-interval '70 days',updated_at=now()-interval '70 days' WHERE id=record_id; PERFORM public.archive_maintenance();"+check('(SELECT archived_at IS NULL FROM public.support_tickets WHERE id=record_id)'))
for hours,enabled,expected in [(2,True,True),(4,True,False),(2,False,False)]:
    add(f'autoapproval/{hours}h/{enabled}',owner()+f"UPDATE public.service_settings SET enabled={str(enabled).lower()} WHERE key='auto_approval_3h'; INSERT INTO public.masses(title,starts_at,published) VALUES('QA automatic',now()+interval '{hours} hours',true) RETURNING id INTO mass_id; INSERT INTO public.assignments(mass_id,function_name,service_group) VALUES(mass_id,'QA slot','cerimoniario') RETURNING id INTO assignment_id;"+actor(3)+f"INSERT INTO public.requests(mass_id,user_id,type,service_group) VALUES(mass_id,'{uid(3)}','servir','cerimoniario');"+owner()+check(f"(SELECT (server_id IS NOT NULL)={str(expected).lower()} FROM public.assignments WHERE id=assignment_id)"))
add('parent/link-request-confirm-unlink',actor(6)+"record_id:=public.request_parent_link('qa-coroinha@example.invalid');"+owner()+f"SELECT substring(body from 'Código: ([0-9]{{6}})') INTO link_code FROM public.notifications WHERE user_id='{uid(2)}' AND event_key='parent_link_code' ORDER BY created_at DESC LIMIT 1;"+actor(6)+check('public.confirm_parent_link(record_id,link_code)')+f"PERFORM public.unlink_parent_child('{uid(6)}','{uid(2)}');"+owner()+check(f"NOT EXISTS(SELECT 1 FROM public.parent_child_links WHERE parent_id='{uid(6)}')"))
add('poll/create-vote-coroinha',actor(4)+"record_id:=public.poll_create('QA pergunta válida','[\"Sim\",\"Não\"]',now(),now()+interval '1 day',false,false);"+owner()+"SELECT id INTO option_id FROM public.poll_options WHERE poll_id=record_id LIMIT 1;"+actor(2)+"result:=public.poll_vote(record_id,ARRAY[option_id]);"+check("(result->>'voted')::boolean"))
add('poll/ceremonial-default-vote',actor(5)+"record_id:=public.poll_create('QA pergunta válida','[\"Sim\",\"Não\"]',now(),now()+interval '1 day',false,false);"+owner()+"SELECT id INTO option_id FROM public.poll_options WHERE poll_id=record_id LIMIT 1;"+actor(3)+"result:=public.poll_vote(record_id,ARRAY[option_id]);"+check("(result->>'voted')::boolean"))
blocks=[]
for name,body in cases:
    blocks.append("BEGIN "+body+" RAISE EXCEPTION 'QA_ROLLBACK_OK'; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS state=RETURNED_SQLSTATE,detail=MESSAGE_TEXT; EXECUTE 'RESET ROLE'; results:=results||jsonb_build_array(jsonb_build_object('name','"+name+"','passed',detail='QA_ROLLBACK_OK','error',CASE WHEN detail='QA_ROLLBACK_OK' THEN NULL ELSE state||': '||detail END)); END;")
sql=header.replace('denied boolean;', 'mass_id uuid; assignment_id uuid; option_id uuid; link_code text; denied boolean;')+'\n'.join(blocks)+"\nINSERT INTO qa_results VALUES(results); END $suite$;"
Path('/tmp/qa-flows.json').write_text(json.dumps(['CREATE TEMP TABLE qa_results(result jsonb);',sql,'SELECT result FROM qa_results;']))
print(len(cases))
